css:
.tpl-outro-brand { position: relative; width: 100%; height: 100%; overflow: hidden; display: flex; align-items: center; justify-content: center; background: radial-gradient(60% 60% at 50% 50%, rgba(124,58,237,0.22) 0%, transparent 65%), var(--bg, #070b14); font-family: var(--font-sans, 'Inter', 'PingFang SC', sans-serif); color: var(--fg, #ffffff); }
.tpl-outro-brand .hero-phase { position: absolute; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: clamp(12px, 2.2vh, 24px); padding: 0 8%; text-align: center; }
.tpl-outro-brand .hero-brand { font-size: clamp(46px, 8.6vmin, 114px); font-weight: 900; letter-spacing: -0.03em; background: linear-gradient(125deg, #ffffff 30%, var(--accent, #a78bfa) 100%); -webkit-background-clip: text; background-clip: text; color: transparent; }
.tpl-outro-brand .hero-tag { font-size: clamp(18px, 2.8vmin, 32px); color: var(--muted, #cbd5e1); letter-spacing: 0.06em; }
.tpl-outro-brand .cta-pill { position: relative; padding: clamp(18px, 3.2vmin, 42px) clamp(38px, 6.8vmin, 96px); border-radius: 999px; background: linear-gradient(135deg, rgba(124,58,237,0.95) 0%, rgba(24,217,232,0.92) 50%, rgba(34,197,94,0.95) 100%); border: 1px solid rgba(255,255,255,0.45); box-shadow: 0 22px 54px rgba(0,0,0,0.42), 0 0 68px rgba(24,217,232,0.28); text-align: center; opacity: 0; }
.tpl-outro-brand .cta-title { font-size: clamp(28px, 4.8vmin, 62px); font-weight: 900; color: #05080f; white-space: nowrap; }
.tpl-outro-brand .cta-sub { margin-top: 4px; font-size: clamp(13px, 1.8vmin, 20px); font-weight: 700; color: rgba(5,8,15,0.78); letter-spacing: 0.05em; }
.tpl-outro-brand .cta-cursor { position: absolute; left: 57%; top: 55%; width: clamp(36px, 5vmin, 64px); height: clamp(36px, 5vmin, 64px); pointer-events: none; opacity: 0; filter: drop-shadow(0 8px 18px rgba(0,0,0,0.45)); }
